G.loadSet=()=>{if(!G.set){try{G.set=Object.assign({bgm:1,sfx:1,fx:1,cut:1,shake:1,dmg:1},JSON.parse(localStorage.getItem('slayers_set')||'{}'))}catch(e){G.set={bgm:1,sfx:1,fx:1,cut:1,shake:1,dmg:1}}}return G.set};G.applySet=()=>{const s=G.loadSet();localStorage.setItem('slayers_set',JSON.stringify(s));R.opt={cut:!!s.cut,shake:!!s.shake,dmg:!!s.dmg,fx:!!s.fx}};G.applySet();{const sb=C.startBoss;C.startBoss=(...a)=>{const s=C.S();if(!C.B.boss)G._bs={g:s.gold,lv:s.lv,ex:s.exp,st:s.stone||0,t:Date.now(),nm:C.stageName(s.si)};const was=C.B.boss,r=sb(...a);if(!was&&C.B.boss)bossWarn(s.si);return r}}
function bossWarn(i){try{if(G.S&&R.opt&&!R.opt.cut)return;const pl=D.BOSSPLAN[Math.floor(i/7)],b=pl&&D.BOSSES[pl[i%7==6?1:0]];if(!b)return;document.querySelectorAll('.bwarn').forEach(x=>x.remove());const d=document.createElement('div');d.className='bwarn';d.innerHTML=`<div class=bwe></div><div class=bws><i>WARNING</i><i>WARNING</i><i>WARNING</i></div><div class=bwm><img src="assets/${b.img}"><div><small>${i%7==6?'챕터 보스':'보스'} 출현</small><b>${b.n}</b>${b.q?`<em>「${b.q}」</em>`:''}</div></div><div class=bws b2><i>WARNING</i><i>WARNING</i><i>WARNING</i></div>`;document.body.appendChild(d);R.hs=Math.max(R.hs||0,.25);R.ccut=null;R.ccCd=Math.max(R.ccCd||0,2.5);setTimeout(()=>d.classList.add('out'),1500);setTimeout(()=>d.remove(),1900)}catch(e){}}
function resultPop(win){const s=C.S(),b=G._bs||{g:s.gold,st:s.stone||0,nm:''};const dg=Math.max(0,s.gold-b.g),ds=Math.max(0,(s.stone||0)-b.st),sec=b.t?((Date.now()-b.t)/1000):0;document.querySelectorAll('.vic,#battle .banner').forEach(x=>x.remove());if(!win)document.querySelectorAll('.toast').forEach(x=>{if(x.textContent.includes('보스 실패'))x.remove()});const d=document.createElement('div');d.className='vic '+(win?'win':'lose');
 d.innerHTML=win?`<div class=vt>VICTORY</div><div class=vs>${b.nm} 클리어 · ${sec.toFixed(1)}초</div><div class=vr><span><img class=ci src=assets/it2_gold.png> +${fmt(dg)}</span>${ds?`<span><img class=ci src=assets/it2_stone.png> +${ds}</span>`:''}${s.lv>b.lv?`<span class=up>Lv.${s.lv} ▲</span>`:''}</div><div class=vn>다음 스테이지 ▶ ${C.stageName(s.si)}</div>`:`<div class=vt>DEFEAT</div><div class=vs>${b.nm} 보스 실패</div><div class=vn>장비 강화 · 동료 육성 후 자동 재도전</div>`;
 document.body.appendChild(d);d.onclick=()=>d.remove();setTimeout(()=>d.classList.add('out'),2300);setTimeout(()=>d.remove(),2700)}
function chapterCard(c,si){const TAG=['평화로운 가도에 몬스터가 들끓는다','마족의 기운이 숲을 뒤덮었다','붉은 마왕이 기다리는 마지막 성'];const show=()=>{document.querySelectorAll('.chap').forEach(x=>x.remove());const d=document.createElement('div');d.className='chap';d.style.setProperty('--art',`url(assets/chap/ch${c+1}.jpg)`);d.innerHTML=`<div class=cl></div><div class=cn>CHAPTER ${c+1}</div><div class=ct>${D.CH[c]||''}</div><div class=cs>${TAG[c]||''}</div><div class=cst>${C.stageName(si)}</div><div class=cl></div>`;document.body.appendChild(d);document.body.classList.add('chapon');const rm=()=>{d.remove();if(!document.querySelector('.chap'))document.body.classList.remove('chapon')};d.onclick=rm;setTimeout(()=>d.classList.add('out'),2600);setTimeout(rm,3100)};if(document.querySelector('.vic:not(.out)'))setTimeout(show,2500);else show()}
